/**
 * Pure configuration, `.env` parsing, Bangumi API user resolution, validation,
 * derivation and redaction helpers for `scripts/setup-staging.sh` (#147).
 *
 * Naming contract: `AIRINGCAL_{ENVIRONMENT}_{SERVICE}_{KEY}`
 *
 * Staging requires at most in local `.env`:
 * - 3 Secrets:
 *   - `AIRINGCAL_STAGING_BANGUMI_TOKEN`
 *   - `AIRINGCAL_STAGING_S3_ACCESS_KEY_ID`
 *   - `AIRINGCAL_STAGING_S3_SECRET_ACCESS_KEY`
 * - 1 Business Variable (`AIRINGCAL_STAGING_USERS_JSON` is auto-generated by
 *   querying the Bangumi API `/v0/users/{username}` / `/v0/me`):
 *   - `AIRINGCAL_STAGING_PRIMARY_USER_ID`
 *
 * Non-sensitive infrastructure values (Account ID, S3 Endpoint, Region,
 * Checkpoint/Public Bucket names, Worker name, Public HTTPS URL) are derived
 * automatically and stored as GitHub Variables, never as Secrets.
 */
import { existsSync, readFileSync } from 'node:fs'
import { pathToFileURL } from 'node:url'

export const ALLOWED_REPOSITORY = 'Skyline-Gazer/AiringCal'
export const ALLOWED_ENVIRONMENT = 'staging'
export const BGM_USER_AGENT = 'markd3ng/AiringCal (https://github.com/markd3ng/AiringCal)'
export const BGM_API_BASE = 'https://api.bgm.tv'

export const STAGING_DEFAULTS = Object.freeze({
  repository: ALLOWED_REPOSITORY,
  environment: ALLOWED_ENVIRONMENT,
  checkpointBucket: 'airingcal-staging-checkpoint',
  publicBucket: 'airingcal-staging-public',
  s3Region: 'auto',
  workerName: 'airing-cal-v3-read-staging',
})

export const FORBIDDEN_PRODUCTION_BUCKETS = Object.freeze([
  'airing-cal-public',
  'airing-cal-images',
  'airing-cal-data',
  'airing-cal-checkpoint',
])

export const FORBIDDEN_PRODUCTION_WORKERS = Object.freeze([
  'airing-cal-frontend',
])

export const STAGING_SECRET_KEYS = Object.freeze([
  'AIRINGCAL_STAGING_BANGUMI_TOKEN',
  'AIRINGCAL_STAGING_S3_ACCESS_KEY_ID',
  'AIRINGCAL_STAGING_S3_SECRET_ACCESS_KEY',
])

export const STAGING_VARIABLE_KEYS = Object.freeze([
  'AIRINGCAL_STAGING_PRIMARY_USER_ID',
  'AIRINGCAL_STAGING_USERS_JSON',
  'AIRINGCAL_STAGING_CLOUDFLARE_ACCOUNT_ID',
  'AIRINGCAL_STAGING_PUBLIC_BASE_URL',
  'AIRINGCAL_STAGING_PUBLIC_R2_BUCKET',
  'AIRINGCAL_STAGING_CHECKPOINT_R2_BUCKET',
  'AIRINGCAL_STAGING_S3_ENDPOINT',
  'AIRINGCAL_STAGING_S3_REGION',
  'AIRINGCAL_STAGING_WORKER_NAME',
])

const BUCKET_NAME_RE = /^[a-z0-9][a-z0-9-]{1,61}[a-z0-9]$/
const WORKER_NAME_RE = /^[a-z0-9][a-z0-9-]{0,61}[a-z0-9]$/
const ACCOUNT_ID_RE = /^[0-9a-f]{32}$/i
const ENV_KEY_RE = /^[A-Za-z_][A-Za-z0-9_]*$/

/**
 * Safe, controlled `.env` parser.
 *
 * Parses key-value pairs as pure data without shell evaluation (`source`/`eval`),
 * preventing command injection via `$()`, backticks, `;`, or pipes while
 * supporting single quotes, double quotes (with standard escapes), spaces, and
 * inline `#` comments.
 */
export function parseDotEnvContent(content) {
  const result = {}
  const lines = String(content ?? '').split(/\r?\n/)

  for (const [index, rawLine] of lines.entries()) {
    const trimmed = rawLine.trim()
    if (!trimmed || trimmed.startsWith('#')) continue

    const withoutExport = trimmed.startsWith('export ')
      ? trimmed.slice('export '.length).trimStart()
      : trimmed
    const eqIndex = withoutExport.indexOf('=')
    if (eqIndex === -1) {
      throw new Error(`Invalid .env syntax at line ${index + 1}: missing '='`)
    }

    const key = withoutExport.slice(0, eqIndex).trim()
    if (!ENV_KEY_RE.test(key)) {
      throw new Error(`Invalid .env key at line ${index + 1}`)
    }

    const rawValue = withoutExport.slice(eqIndex + 1).trimStart()
    if (rawValue.length === 0) {
      result[key] = ''
      continue
    }

    if (rawValue.startsWith("'")) {
      const closing = rawValue.indexOf("'", 1)
      if (closing === -1) {
        throw new Error(`Unterminated single-quoted value for ${key} at line ${index + 1}`)
      }
      const trailing = rawValue.slice(closing + 1).trim()
      if (trailing && !trailing.startsWith('#')) {
        throw new Error(`Unexpected trailing characters after single-quoted value for ${key} at line ${index + 1}`)
      }
      result[key] = rawValue.slice(1, closing)
      continue
    }

    if (rawValue.startsWith('"')) {
      let value = ''
      let closed = false
      let i = 1
      while (i < rawValue.length) {
        const ch = rawValue[i]
        if (ch === '\\') {
          if (i + 1 >= rawValue.length) {
            throw new Error(`Trailing escape in double-quoted value for ${key} at line ${index + 1}`)
          }
          const next = rawValue[i + 1]
          if (next === 'n') value += '\n'
          else if (next === 'r') value += '\r'
          else if (next === 't') value += '\t'
          else if (next === '"' || next === '\\' || next === '$') value += next
          else value += next
          i += 2
          continue
        }
        if (ch === '"') {
          closed = true
          i += 1
          break
        }
        value += ch
        i += 1
      }
      if (!closed) {
        throw new Error(`Unterminated double-quoted value for ${key} at line ${index + 1}`)
      }
      const trailing = rawValue.slice(i).trim()
      if (trailing && !trailing.startsWith('#')) {
        throw new Error(`Unexpected trailing characters after double-quoted value for ${key} at line ${index + 1}`)
      }
      result[key] = value
      continue
    }

    // Unquoted value: strip inline ` #...` comment when `#` is preceded by whitespace
    let unquoted = rawValue
    for (let i = 0; i < rawValue.length; i++) {
      if (rawValue[i] === '#' && (i === 0 || /\s/.test(rawValue[i - 1]))) {
        unquoted = rawValue.slice(0, i)
        break
      }
    }
    result[key] = unquoted.trimEnd()
  }

  return result
}

/**
 * Loads `.env` from `filePath` (read-only; never modifies `.env` on disk) and
 * merges non-empty values into a copy of `baseEnv`. Existing non-empty values in
 * `baseEnv` take precedence unless `override: true` is passed.
 */
export function loadDotEnvFile(filePath, baseEnv = process.env, { override = false } = {}) {
  const merged = { ...baseEnv }
  if (!filePath || !existsSync(filePath)) return merged
  const content = readFileSync(filePath, 'utf8')
  const parsed = parseDotEnvContent(content)
  for (const [key, value] of Object.entries(parsed)) {
    const existing = merged[key]
    if (override || existing === undefined || existing === '') {
      if (value !== '' || existing === undefined) {
        merged[key] = value
      }
    }
  }
  return merged
}

/**
 * Validates that `usersJson` and `primaryUserId` satisfy the exact `node-jobs`
 * contract (`apps/node-jobs/src/sync/config.ts` and `upstream/fetch.ts`).
 */
export function validateNodeJobsUsersContract(usersJson, primaryUserId) {
  const id = (primaryUserId ?? '').trim()
  if (!id) {
    throw new Error('AIRINGCAL_STAGING_PRIMARY_USER_ID is required')
  }
  let parsed
  try {
    parsed = JSON.parse((usersJson ?? '').trim())
  } catch {
    throw new Error('AIRINGCAL_STAGING_USERS_JSON must be valid JSON')
  }
  if (!Array.isArray(parsed) || parsed.length === 0) {
    throw new Error('AIRINGCAL_STAGING_USERS_JSON must be a non-empty JSON array')
  }
  const seenIds = new Set()
  const normalized = parsed.map((entry) => {
    if (!entry || typeof entry !== 'object' || Array.isArray(entry)) {
      throw new Error('AIRINGCAL_STAGING_USERS_JSON entries must be objects')
    }
    const userId =
      typeof entry.userId === 'string'
        ? entry.userId.trim()
        : typeof entry.user_id === 'string'
          ? entry.user_id.trim()
          : ''
    const username = typeof entry.username === 'string' ? entry.username.trim() : ''
    if (!userId || !username) {
      throw new Error('AIRINGCAL_STAGING_USERS_JSON entries require non-empty userId and username')
    }
    if (seenIds.has(userId)) {
      throw new Error(`AIRINGCAL_STAGING_USERS_JSON contains duplicate userId "${userId}"`)
    }
    seenIds.add(userId)
    return { userId, username }
  })
  if (!seenIds.has(id)) {
    throw new Error(
      `AIRINGCAL_STAGING_USERS_JSON must contain an entry with userId matching AIRINGCAL_STAGING_PRIMARY_USER_ID (${id})`,
    )
  }
  return {
    primaryUserId: id,
    users: normalized,
    usersJson: JSON.stringify(normalized),
  }
}

function parseBgmUserPayload(payload, contextLabel) {
  if (!payload || typeof payload !== 'object' || Array.isArray(payload)) {
    throw new Error(`Bangumi API (${contextLabel}) returned a non-object user payload`)
  }
  const id = payload.id
  const username = typeof payload.username === 'string' ? payload.username.trim() : ''
  if (!Number.isSafeInteger(id) || id <= 0 || !username) {
    throw new Error(`Bangumi API (${contextLabel}) response is missing valid id or username`)
  }
  return {
    userId: String(id),
    username,
    nickname: typeof payload.nickname === 'string' ? payload.nickname : username,
  }
}

/**
 * Queries Bangumi API (`GET /v0/users/{username}`, with `/v0/me` fallback on 404
 * when the user customized their username and passed a numeric UID, per
 * `docs/example/api/bgm-api.json` `#/components/parameters/path_username`).
 *
 * Throws an explicit Error if resolution fails — never guesses `username = primaryUserId`.
 */
export async function resolveBangumiUser({
  primaryUserId,
  bangumiToken,
  fetchImpl = globalThis.fetch,
  apiBase = BGM_API_BASE,
  timeoutMs = 15_000,
} = {}) {
  const target = (primaryUserId ?? '').trim()
  if (!target) {
    throw new Error('AIRINGCAL_STAGING_PRIMARY_USER_ID is required to resolve Bangumi user')
  }
  if (typeof fetchImpl !== 'function') {
    throw new Error('fetch implementation is required to query Bangumi API')
  }

  const base = apiBase.replace(/\/+$/, '')
  const token = (bangumiToken ?? '').trim()
  const headers = {
    'User-Agent': BGM_USER_AGENT,
    Accept: 'application/json',
    ...(token ? { Authorization: `Bearer ${token}` } : {}),
  }

  const userUrl = `${base}/v0/users/${encodeURIComponent(target)}`
  let res
  try {
    res = await fetchImpl(userUrl, {
      method: 'GET',
      headers,
      signal: AbortSignal.timeout(timeoutMs),
    })
  } catch (error) {
    const reason = error instanceof Error ? error.message : String(error)
    throw new Error(`Failed to query Bangumi user API (${userUrl}): ${ redactSecrets(reason, [token]) }`)
  }

  if (res.status === 200) {
    let body
    try {
      body = await res.json()
    } catch {
      throw new Error(`Bangumi API (${userUrl}) returned invalid JSON`)
    }
    const resolved = parseBgmUserPayload(body, `/v0/users/${target}`)
    if (resolved.userId !== target && resolved.username !== target) {
      throw new Error(
        `Bangumi API user mismatch: requested "${target}", got id=${resolved.userId} username=${resolved.username}`,
      )
    }
    return resolved
  }

  // Per docs/example/api/bgm-api.json: once a user sets a custom username,
  // `/v0/users/{uid}` returns 404. If a token is provided, check `/v0/me`.
  if (res.status === 404 && token) {
    const meUrl = `${base}/v0/me`
    let meRes
    try {
      meRes = await fetchImpl(meUrl, {
        method: 'GET',
        headers,
        signal: AbortSignal.timeout(timeoutMs),
      })
    } catch (error) {
      const reason = error instanceof Error ? error.message : String(error)
      throw new Error(
        `Bangumi user "${target}" not found at /v0/users/${target} (404) and /v0/me fallback failed: ${redactSecrets(reason, [token])}`,
      )
    }
    if (meRes.status === 200) {
      let meBody
      try {
        meBody = await meRes.json()
      } catch {
        throw new Error('Bangumi API (/v0/me) returned invalid JSON')
      }
      const me = parseBgmUserPayload(meBody, '/v0/me')
      if (me.userId !== target && me.username !== target) {
        throw new Error(
          `Bangumi user "${target}" returned 404 on /v0/users/${target}, and token owner (/v0/me) is id=${me.userId} username=${me.username} (does not match "${target}")`,
        )
      }
      return me
    }
  }

  throw new Error(
    `Bangumi API failed to resolve user "${target}" (HTTP ${res.status} from ${userUrl}). Verify AIRINGCAL_STAGING_PRIMARY_USER_ID or pass --username / --users-json explicitly.`,
  )
}

/**
 * Resolves and validates `primaryUserId` and `usersJson`.
 *
 * Priority:
 * 1. Explicit `usersJson` (`--users-json` or `AIRINGCAL_STAGING_USERS_JSON`)
 * 2. Explicit `username` (`--username` or `AIRINGCAL_STAGING_BANGUMI_USERNAME`)
 * 3. Live Bangumi API lookup (`resolveBangumiUser`)
 */
export async function resolveUsersConfig({
  usersJson,
  primaryUserId,
  username,
  bangumiToken,
  fetchImpl = globalThis.fetch,
  apiBase = BGM_API_BASE,
} = {}) {
  const id = (primaryUserId ?? '').trim()
  if (!id) {
    throw new Error('AIRINGCAL_STAGING_PRIMARY_USER_ID is required')
  }

  const rawJson = (usersJson ?? '').trim()
  if (rawJson) {
    return validateNodeJobsUsersContract(rawJson, id)
  }

  const explicitUsername = (username ?? '').trim()
  if (explicitUsername) {
    const generated = JSON.stringify([{ userId: id, username: explicitUsername }])
    return validateNodeJobsUsersContract(generated, id)
  }

  const resolvedUser = await resolveBangumiUser({
    primaryUserId: id,
    bangumiToken,
    fetchImpl,
    apiBase,
  })
  const canonicalPrimaryId = resolvedUser.userId
  const generated = JSON.stringify([
    { userId: canonicalPrimaryId, username: resolvedUser.username },
  ])
  return validateNodeJobsUsersContract(generated, canonicalPrimaryId)
}

export function validateStagingPublicBaseUrl(rawUrl) {
  const trimmed = (rawUrl ?? '').trim().replace(/\/+$/, '')
  if (!trimmed) {
    throw new Error('AIRINGCAL_STAGING_PUBLIC_BASE_URL is required')
  }
  if (/placeholder/i.test(trimmed)) {
    throw new Error('AIRINGCAL_STAGING_PUBLIC_BASE_URL must not be a placeholder value')
  }
  let parsed
  try {
    parsed = new URL(trimmed)
  } catch {
    throw new Error('AIRINGCAL_STAGING_PUBLIC_BASE_URL must be an absolute https URL')
  }
  if (parsed.protocol !== 'https:' || parsed.search !== '' || parsed.hash !== '') {
    throw new Error(
      'AIRINGCAL_STAGING_PUBLIC_BASE_URL must be an absolute https URL without query or fragment',
    )
  }
  return trimmed
}

/**
 * Verifies that `wrangler r2 bucket dev-url get <checkpoint_bucket>` confirms
 * public `r2.dev` access is disabled.
 */
export function assertCheckpointBucketPrivate(devUrlGetOutput, bucketName = STAGING_DEFAULTS.checkpointBucket) {
  const text = String(devUrlGetOutput ?? '')
  if (/Public access is enabled/i.test(text) || /https:\/\/pub-[a-z0-9]+\.r2\.dev/i.test(text)) {
    throw new Error(
      `Security violation: checkpoint bucket "${bucketName}" still has public r2.dev access enabled`,
    )
  }
  if (!/Public access via the r2\.dev URL is disabled/i.test(text)) {
    throw new Error(
      `Could not confirm that checkpoint bucket "${bucketName}" has r2.dev public access disabled`,
    )
  }
  return true
}

/**
 * Classifies `/api/health` response from the Staging Read Worker.
 *
 * Before Generation 1 is published, `503` with `code: "NO_RELEASE"` is expected
 * and is classified as `uninitialized_no_release` (`readerAcceptance: "not_initialized"`),
 * NEVER as a Reader acceptance PASS.
 */
export function classifyStagingWorkerHealth(statusCode, bodyText) {
  const status = Number(statusCode)
  let parsed = null
  try {
    parsed = JSON.parse(String(bodyText ?? ''))
  } catch {
    parsed = null
  }

  if (
    status === 200 &&
    parsed?.ok === true &&
    Number.isSafeInteger(parsed?.data?.publish?.generation) &&
    parsed.data.publish.generation >= 1
  ) {
    return {
      state: 'ready',
      generation: parsed.data.publish.generation,
      readerAcceptance: 'pass',
    }
  }

  if (status === 503 && parsed?.error?.code === 'NO_RELEASE') {
    return {
      state: 'uninitialized_no_release',
      generation: null,
      readerAcceptance: 'not_initialized',
    }
  }

  const code = parsed?.error?.code ? ` (${parsed.error.code})` : ''
  throw new Error(
    `Staging Worker /api/health verification failed with HTTP ${status}${code}`,
  )
}

/**
 * Validates and derives the full non-sensitive Staging configuration + secret presence
 * summary (never includes raw secret values in the returned `variables` or `summary`).
 */
export async function deriveStagingConfig(
  env = process.env,
  { fetchImpl = globalThis.fetch, apiBase = BGM_API_BASE } = {},
) {
  const repository = (env.AIRINGCAL_REPOSITORY ?? STAGING_DEFAULTS.repository).trim()
  if (repository !== ALLOWED_REPOSITORY) {
    throw new Error(
      `Cross-repository guard: setup-staging only operates on ${ALLOWED_REPOSITORY} (got "${repository}")`,
    )
  }

  const environment = (env.AIRINGCAL_TARGET_ENVIRONMENT ?? STAGING_DEFAULTS.environment).trim()
  if (environment !== ALLOWED_ENVIRONMENT) {
    throw new Error(
      `Cross-environment guard: setup-staging only operates on environment "${ALLOWED_ENVIRONMENT}" (got "${environment}")`,
    )
  }

  const checkpointBucket = (
    env.AIRINGCAL_STAGING_CHECKPOINT_R2_BUCKET ?? STAGING_DEFAULTS.checkpointBucket
  ).trim()
  const publicBucket = (
    env.AIRINGCAL_STAGING_PUBLIC_R2_BUCKET ?? STAGING_DEFAULTS.publicBucket
  ).trim()

  for (const [label, bucket] of [
    ['AIRINGCAL_STAGING_CHECKPOINT_R2_BUCKET', checkpointBucket],
    ['AIRINGCAL_STAGING_PUBLIC_R2_BUCKET', publicBucket],
  ]) {
    if (!BUCKET_NAME_RE.test(bucket)) {
      throw new Error(`${label} must be a valid R2 bucket name (3-63 lowercase chars, got "${bucket}")`)
    }
    if (FORBIDDEN_PRODUCTION_BUCKETS.includes(bucket)) {
      throw new Error(
        `Cross-environment guard: ${label} must never use production bucket "${bucket}"`,
      )
    }
  }
  if (checkpointBucket === publicBucket) {
    throw new Error('Staging checkpoint bucket and public bucket must be distinct')
  }

  const workerName = (env.AIRINGCAL_STAGING_WORKER_NAME ?? STAGING_DEFAULTS.workerName).trim()
  if (!WORKER_NAME_RE.test(workerName)) {
    throw new Error(`AIRINGCAL_STAGING_WORKER_NAME must be a valid lowercase Worker name (got "${workerName}")`)
  }
  if (FORBIDDEN_PRODUCTION_WORKERS.includes(workerName)) {
    throw new Error(
      `Cross-environment guard: AIRINGCAL_STAGING_WORKER_NAME must never overwrite production worker "${workerName}"`,
    )
  }

  const accountId = (
    env.AIRINGCAL_STAGING_CLOUDFLARE_ACCOUNT_ID ??
    env.CLOUDFLARE_ACCOUNT_ID ??
    ''
  )
    .trim()
    .toLowerCase()
  if (!ACCOUNT_ID_RE.test(accountId)) {
    throw new Error(
      'AIRINGCAL_STAGING_CLOUDFLARE_ACCOUNT_ID (or CLOUDFLARE_ACCOUNT_ID) must be a 32-character hex Cloudflare account id',
    )
  }

  const s3Endpoint = (
    env.AIRINGCAL_STAGING_S3_ENDPOINT?.trim() ||
    `https://${accountId}.r2.cloudflarestorage.com`
  ).replace(/\/+$/, '')
  let parsedEndpoint
  try {
    parsedEndpoint = new URL(s3Endpoint)
  } catch {
    throw new Error('AIRINGCAL_STAGING_S3_ENDPOINT must be a valid URL')
  }
  if (parsedEndpoint.protocol !== 'https:') {
    throw new Error('AIRINGCAL_STAGING_S3_ENDPOINT must use https://')
  }

  const s3Region = (env.AIRINGCAL_STAGING_S3_REGION ?? STAGING_DEFAULTS.s3Region).trim() || 'auto'

  const bangumiToken = (env.AIRINGCAL_STAGING_BANGUMI_TOKEN ?? env.BGM_TOKEN ?? '').trim()
  const s3AccessKeyId = (env.AIRINGCAL_STAGING_S3_ACCESS_KEY_ID ?? '').trim()
  const s3SecretAccessKey = (env.AIRINGCAL_STAGING_S3_SECRET_ACCESS_KEY ?? '').trim()
  const cloudflareApiToken = (
    env.AIRINGCAL_STAGING_CLOUDFLARE_API_TOKEN ??
    env.CLOUDFLARE_API_TOKEN ??
    ''
  ).trim()

  const userResolved = await resolveUsersConfig({
    usersJson: env.AIRINGCAL_STAGING_USERS_JSON,
    primaryUserId: env.AIRINGCAL_STAGING_PRIMARY_USER_ID,
    username: env.AIRINGCAL_STAGING_BANGUMI_USERNAME,
    bangumiToken,
    fetchImpl,
    apiBase,
  })

  const publicBaseUrl = validateStagingPublicBaseUrl(env.AIRINGCAL_STAGING_PUBLIC_BASE_URL)

  const variables = {
    AIRINGCAL_STAGING_PRIMARY_USER_ID: userResolved.primaryUserId,
    AIRINGCAL_STAGING_USERS_JSON: userResolved.usersJson,
    AIRINGCAL_STAGING_CLOUDFLARE_ACCOUNT_ID: accountId,
    AIRINGCAL_STAGING_PUBLIC_BASE_URL: publicBaseUrl,
    AIRINGCAL_STAGING_PUBLIC_R2_BUCKET: publicBucket,
    AIRINGCAL_STAGING_CHECKPOINT_R2_BUCKET: checkpointBucket,
    AIRINGCAL_STAGING_S3_ENDPOINT: s3Endpoint,
    AIRINGCAL_STAGING_S3_REGION: s3Region,
    AIRINGCAL_STAGING_WORKER_NAME: workerName,
  }

  const secretsConfigured = {
    AIRINGCAL_STAGING_BANGUMI_TOKEN: bangumiToken.length > 0,
    AIRINGCAL_STAGING_S3_ACCESS_KEY_ID: s3AccessKeyId.length > 0,
    AIRINGCAL_STAGING_S3_SECRET_ACCESS_KEY: s3SecretAccessKey.length > 0,
  }
  const missingSecrets = Object.entries(secretsConfigured)
    .filter(([, present]) => !present)
    .map(([key]) => key)

  return {
    repository,
    environment,
    variables,
    secretsConfigured,
    optionalCloudflareTokenPresent: cloudflareApiToken.length > 0,
    missingSecrets,
  }
}

/**
 * Extracts the 32-hex Cloudflare Account ID from `wrangler whoami --json` output.
 */
export function parseWranglerWhoamiJson(raw) {
  let data
  try {
    data = JSON.parse(raw)
  } catch {
    throw new Error('Failed to parse wrangler whoami --json output')
  }
  if (!data || data.loggedIn === false) {
    throw new Error('Wrangler is not authenticated; set AIRINGCAL_STAGING_CLOUDFLARE_API_TOKEN in .env or run wrangler login')
  }
  const accounts = Array.isArray(data.accounts) ? data.accounts : []
  const firstId = accounts.find((acc) => typeof acc?.id === 'string' && ACCOUNT_ID_RE.test(acc.id))?.id
  if (!firstId) {
    throw new Error('Could not resolve a 32-hex Cloudflare Account ID from wrangler whoami')
  }
  return firstId.toLowerCase()
}

/**
 * Extracts the `https://pub-...r2.dev` URL from `wrangler r2 bucket dev-url get` output.
 */
export function parseWranglerDevUrlOutput(raw) {
  const match = String(raw ?? '').match(/https:\/\/pub-[a-z0-9]+\.r2\.dev/i)
  if (!match) {
    throw new Error('Could not extract https://pub-*.r2.dev URL from wrangler r2 bucket dev-url output')
  }
  return match[0].toLowerCase()
}

/**
 * Redacts known secret values and bearer tokens from any diagnostic string.
 */
export function redactSecrets(text, secretValues = []) {
  let out = String(text ?? '')
  for (const secret of secretValues) {
    const trimmed = typeof secret === 'string' ? secret.trim() : ''
    if (trimmed.length >= 4) {
      out = out.split(trimmed).join('[REDACTED]')
    }
  }
  out = out.replace(/(Authorization:\s*Bearer\s+)[A-Za-z0-9._-]+/gi, '$1[REDACTED]')
  return out
}

async function readStdinText() {
  const chunks = []
  for await (const chunk of process.stdin) chunks.push(chunk)
  return Buffer.concat(chunks).toString('utf8')
}

async function runCli() {
  const [, , cmd, ...rest] = process.argv
  const envFile = process.env.AIRINGCAL_DOTENV_PATH ?? '.env'
  const env = loadDotEnvFile(envFile, process.env)
  const secretList = [
    env.AIRINGCAL_STAGING_BANGUMI_TOKEN,
    env.BGM_TOKEN,
    env.AIRINGCAL_STAGING_S3_ACCESS_KEY_ID,
    env.AIRINGCAL_STAGING_S3_SECRET_ACCESS_KEY,
    env.AIRINGCAL_STAGING_CLOUDFLARE_API_TOKEN,
    env.CLOUDFLARE_API_TOKEN,
  ]

  try {
    if (cmd === 'resolve-users') {
      const primaryUserId = rest[0] || env.AIRINGCAL_STAGING_PRIMARY_USER_ID || ''
      const usersJson = rest[1] || env.AIRINGCAL_STAGING_USERS_JSON || ''
      const username = rest[2] || env.AIRINGCAL_STAGING_BANGUMI_USERNAME || ''
      const resolved = await resolveUsersConfig({
        usersJson,
        primaryUserId,
        username,
        bangumiToken: env.AIRINGCAL_STAGING_BANGUMI_TOKEN ?? env.BGM_TOKEN,
      })
      process.stdout.write(`${JSON.stringify(resolved)}\n`)
      return
    }
    if (cmd === 'parse-whoami') {
      process.stdout.write(parseWranglerWhoamiJson(await readStdinText()))
      return
    }
    if (cmd === 'parse-dev-url') {
      process.stdout.write(parseWranglerDevUrlOutput(await readStdinText()))
      return
    }
    if (cmd === 'assert-checkpoint-private') {
      const bucket = rest[0] || STAGING_DEFAULTS.checkpointBucket
      assertCheckpointBucketPrivate(await readStdinText(), bucket)
      return
    }
    if (cmd === 'classify-health') {
      const statusCode = Number(rest[0] ?? '0')
      const bodyText = await readStdinText()
      const verdict = classifyStagingWorkerHealth(statusCode, bodyText)
      process.stdout.write(`${JSON.stringify(verdict)}\n`)
      return
    }
    if (cmd === 'sync-github') {
      const { spawnSync } = await import('node:child_process')
      const derived = await deriveStagingConfig(env)
      const repo = derived.repository
      const envName = derived.environment

      for (const [varName, varValue] of Object.entries(derived.variables)) {
        const res = spawnSync(
          'gh',
          ['variable', 'set', varName, '--env', envName, '--repo', repo, '--body', String(varValue)],
          { encoding: 'utf8' },
        )
        if (res.status !== 0) {
          throw new Error(`Failed to set GitHub variable ${varName}: ${redactSecrets(res.stderr || res.stdout, secretList)}`)
        }
      }

      const listRes = spawnSync(
        'gh',
        ['secret', 'list', '--env', envName, '--repo', repo, '--json', 'name', '--jq', '.[].name'],
        { encoding: 'utf8' },
      )
      const existingSecrets = new Set(
        (listRes.stdout ?? '')
          .split(/\r?\n/)
          .map((s) => s.trim())
          .filter(Boolean),
      )

      const secretMap = {
        AIRINGCAL_STAGING_BANGUMI_TOKEN: (env.AIRINGCAL_STAGING_BANGUMI_TOKEN ?? env.BGM_TOKEN ?? '').trim(),
        AIRINGCAL_STAGING_S3_ACCESS_KEY_ID: (env.AIRINGCAL_STAGING_S3_ACCESS_KEY_ID ?? '').trim(),
        AIRINGCAL_STAGING_S3_SECRET_ACCESS_KEY: (env.AIRINGCAL_STAGING_S3_SECRET_ACCESS_KEY ?? '').trim(),
      }
      const missingSecrets = []
      const syncedSecrets = []
      const reusedSecrets = []

      for (const [secName, secVal] of Object.entries(secretMap)) {
        if (secVal) {
          const res = spawnSync(
            'gh',
            ['secret', 'set', secName, '--env', envName, '--repo', repo],
            { input: secVal, encoding: 'utf8' },
          )
          if (res.status !== 0) {
            throw new Error(`Failed to set GitHub secret ${secName}: ${redactSecrets(res.stderr || res.stdout, secretList)}`)
          }
          syncedSecrets.push(secName)
        } else if (existingSecrets.has(secName)) {
          reusedSecrets.push(secName)
        } else {
          missingSecrets.push(secName)
        }
      }

      const cfToken = (env.AIRINGCAL_STAGING_CLOUDFLARE_API_TOKEN ?? env.CLOUDFLARE_API_TOKEN ?? '').trim()
      let cfSecretState = 'not_configured_oauth_or_local_only'
      if (cfToken) {
        const res = spawnSync(
          'gh',
          ['secret', 'set', 'AIRINGCAL_STAGING_CLOUDFLARE_API_TOKEN', '--env', envName, '--repo', repo],
          { input: cfToken, encoding: 'utf8' },
        )
        if (res.status !== 0) {
          throw new Error(`Failed to set AIRINGCAL_STAGING_CLOUDFLARE_API_TOKEN: ${redactSecrets(res.stderr || res.stdout, secretList)}`)
        }
        cfSecretState = 'synced'
      } else if (existingSecrets.has('AIRINGCAL_STAGING_CLOUDFLARE_API_TOKEN')) {
        cfSecretState = 'reused'
      }

      process.stdout.write(
        `${JSON.stringify({
          variablesSynced: Object.keys(derived.variables),
          secretsSynced: syncedSecrets,
          secretsReused: reusedSecrets,
          missingSecrets,
          cloudflareGhaSecret: cfSecretState,
        })}\n`,
      )
      if (missingSecrets.length > 0) {
        process.exit(2)
      }
      return
    }
    if (cmd === 'derive') {
      const derived = await deriveStagingConfig(env)
      process.stdout.write(`${JSON.stringify(derived, null, 2)}\n`)
      return
    }
    if (cmd === 'read-cf-token') {
      // Used internally by setup-staging.sh via fd pipe when a token is in .env
      const tok = (env.AIRINGCAL_STAGING_CLOUDFLARE_API_TOKEN ?? env.CLOUDFLARE_API_TOKEN ?? '').trim()
      if (tok) process.stdout.write(tok)
      return
    }
    console.error(
      'Usage: node scripts/setup-staging-lib.mjs <derive|resolve-users|parse-whoami|parse-dev-url|assert-checkpoint-private|classify-health|sync-github>',
    )
    process.exit(1)
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error)
    console.error(redactSecrets(message, secretList))
    process.exit(1)
  }
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  runCli()
}
